export function itemName(id){const e=ITEMS[String(id)];return e?e[0]:("#"+id);}

const REVERSE=new Map();for(const[id,[name,short]]of Object.entries(ITEMS)){REVERSE.set(name.toLowerCase(),id);if(short)REVERSE.set(short.toLowerCase(),id);}
// Fold Russian aliases in: shortName -> id (via REVERSE), then RU name -> id.
// English keys win on collision (only add when absent). RU_INDEX backs substring search.
const RU_INDEX=[];const RU_NAME=new Map();for(const[short,names]of Object.entries(RU_ALIASES)){const id=REVERSE.get(short.toLowerCase());if(!id)continue;if(names[0])RU_NAME.set(String(id),names[0]);for(const n of names){const k=n.toLowerCase();if(!REVERSE.has(k))REVERSE.set(k,id);RU_INDEX.push([k,id]);}}

// Canonical Russian name for an id (first alias), falling back to the English
// display name when we have no translation. Used in user-facing economy output.
export function itemNameRu(id){return RU_NAME.get(String(id))||itemName(id);}

export function resolveItemId(query){const q=String(query).trim();if(/^-?\d+$/.test(q))return q;const lc=q.toLowerCase();if(REVERSE.has(lc))return REVERSE.get(lc);for(const[id,[name,short]]of Object.entries(ITEMS)){if(name.toLowerCase().includes(lc)||(short&&short.toLowerCase().includes(lc)))return id;}for(const[k,id]of RU_INDEX){if(k.includes(lc))return id;}return null;}

// Resolve a trailing currency token ("сера", "scrap") to its item id, or null.
export function resolveCurrencyId(token){const s=CURRENCY_ALIASES[String(token).trim().toLowerCase()];return s?Number(resolveItemId(s)):null;}

// Split a price query into { itemId, currencyId }. The last word is treated as
// a currency only when it's a known currency alias AND the rest resolves to an
// item — so "/price ракета" and "/price ракета сера" both work.
export function parseItemQuery(input){
  const parts=String(input).trim().split(/\s+/).filter(Boolean);
  if(parts.length>=2){
    const curId=resolveCurrencyId(parts[parts.length-1]);
    if(curId!=null){
      const itemId=resolveItemId(parts.slice(0,-1).join(' '));
      if(itemId!=null)return{itemId:Number(itemId),currencyId:curId};
    }
  }
  const itemId=resolveItemId(input);
  return{itemId:itemId!=null?Number(itemId):null,currencyId:null};
}
